int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf)
{
    struct smb_hdr *smb;
    struct smb_composite_search_req *req;
    struct smb_composite_search_rsp *rsp;
    int rc = 0;
    int bytes_returned = 0;

    smb = cifs_ses_alloc(xid, tcon->ses, SMB_COMPOSITE_SEARCH);
    if (!smb)
        return -ENOMEM;

    req = (struct smb_composite_search_req *)((char *)smb + sizeof(struct smb_hdr));

    req->searchHandle = searchHandle;
    req->flags = 0;
    req->infoLevel = psrch_inf->info_level;
    req->maxDataLen = cpu_to_le32(psrch_inf->max_entries);

    rc = SendReceive(xid, tcon->ses, (struct smb_hdr *)smb, (struct smb_hdr **)&rsp, &bytes_returned);
    if (rc != 0)
        goto out;

    if (le32_to_cpu(rsp->byteCount) == 0) {
        psrch_inf->end_of_search = true;
        goto out;
    }

    psrch_inf->entries_found = le32_to_cpu(rsp->entriesReturned);
    psrch_inf->current_idx += psrch_inf->entries_found;

    if (psrch_inf->current_idx >= psrch_inf->max_entries) {
        psrch_inf->end_of_search = true;
    }

out:
    kfree(smb);
    return rc;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf) {
    int rc = 0;
    struct smb2_search_msg req;
    struct smb2_search_response response;
    int bytes_returned;

    /* Initialize the search request message */
    memset(&req, 0, sizeof(req));
    req.searchHandle = searchHandle;
    req.searchFlags = psrch_inf->searchFlags;
    req.searchPattern = psrch_inf->searchPattern;
    req.maxEntries = psrch_inf->maxEntries;

    /* Send the request to the server */
    rc = SMB2_search_send(xid, tcon, &req, &bytes_returned);
    if (rc < 0) {
        return rc;
    }

    /* Receive and process the response */
    rc = SMB2_search_recv(xid, tcon, &response);
    if (rc < 0) {
        return rc;
    }

    /* Update the search information structure with the response */
    psrch_inf->fileCount = response.fileCount;
    psrch_inf->endOfSearch = response.endOfSearch;

    if (response.endOfSearch) {
        psrch_inf->searchFlags |= CIFS_SEARCH_END;
    }

    return 0;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf) {
    struct smb_hdr *smb;
    struct smb2_query_directory_request *req;
    struct smb2_query_directory_response *rsp;
    int rc = 0;

    /* Initialize the SMB2 request */
    smb = cifs_smb2_init(xid, tcon, SMB2_OP_QUERY_DIRECTORY, sizeof(struct smb2_query_directory_request), NULL, 0, NULL);
    if (!smb) {
        return -ENOMEM;
    }

    req = (struct smb2_query_directory_request *) smb;
    req->FileId = searchHandle;
    req->FileInformationClass = psrch_inf->InfoLevel;
    req->FileIndex = psrch_inf->LastIndex;
    req->OutputBufferLength = psrch_inf->MaxDataLen;

    /* Send the request to the server */
    rc = cifs_call_ioctl(xid, tcon, (char *) smb, smb->smb2_buf_length, 0);
    if (rc < 0) {
        goto out;
    }

    /* Parse the response */
    rsp = (struct smb2_query_directory_response *) smb;
    if (rsp->OutputBufferLength == 0) {
        psrch_inf->EndOfSearch = true;
    } else {
        psrch_inf->LastIndex = rsp->NextEntryOffset;
        psrch_inf->Data = (char *) rsp + sizeof(struct smb2_query_directory_response);
        psrch_inf->DataLen = rsp->OutputBufferLength;
    }

out:
    cifs_smb2_free(smb);
    return rc;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf)
{
    struct smb2_search_request *req;
    struct smb2_search_response *resp;
    int rc = 0;

    req = cifs_smb2_init(SMB2_OP_SEARCH_NEXT, tcon, (void **)&resp, sizeof(*resp));
    if (!req)
        return -ENOMEM;

    req->search_handle = searchHandle;
    req->search_criteria = psrch_inf->search_criteria;
    req->max_results = psrch_inf->max_results;

    rc = cifs_send_recv(xid, tcon, (char *)req, CIFS_SEARCH, (char **)&resp);
    if (rc != 0) {
        cifs_smb2_free(req);
        return rc;
    }

    psrch_inf->search_handle = resp->search_handle;
    psrch_inf->has_next = resp->has_next;
    psrch_inf->search_results = resp->search_results;
    psrch_inf->num_results = resp->num_results;

    if (!resp->has_next)
        psrch_inf->end_of_search = true;

    cifs_smb2_free(req);
    return 0;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf)
{
    struct smb_hdr *smb;
    int rc = 0;
    struct kvec iov[1];
    int resp_buf_type;
    char *iov_buf = NULL;
    int bytes_returned;
    struct cifs_search_data *srch_data = NULL;

    if (!tcon || !psrch_inf) {
        return -EINVAL;
    }

    iov_buf = kmalloc(sizeof(struct smb_hdr) + 100, GFP_KERNEL);
    if (!iov_buf)
        return -ENOMEM;

    smb = (struct smb_hdr *)iov_buf;
    memset(smb, 0, sizeof(struct smb_hdr));
    smb->Protocol[0] = 'A';
    smb->Protocol[1] = 'S';
    smb->Protocol[2] = 'C';
    smb->Protocol[3] = 'B';
    smb->Type = SMBtrans2;

    iov[0].iov_base = iov_buf;
    iov[0].iov_len = sizeof(struct smb_hdr) + 100;

    rc = SMBd_send(xid, tcon, iov, 1, &resp_buf_type, &bytes_returned);
    if (rc < 0)
        goto out;

    srch_data = (struct cifs_search_data *)((char *)iov_buf + sizeof(struct smb_hdr));
    if (!srch_data) {
        rc = -EINVAL;
        goto out;
    }

    if (bytes_returned < sizeof(struct cifs_search_data)) {
        rc = -EINVAL;
        goto out;
    }

    psrch_inf->last_entry = 0;
    psrch_inf->end_of_search = (srch_data->end_of_search) ? 1 : 0;
    memcpy(&(psrch_inf->entries[psrch_inf->num_entries++]), srch_data, sizeof(struct cifs_search_data));

    rc = 0;

out:
    if (iov_buf)
        kfree(iov_buf);
    return rc;
}
